begin;
alter table public.announcements add column if not exists popup_enabled boolean not null default false;
alter table public.announcements add column if not exists popup_target_grades text[] not null default '{}'::text[];
create table if not exists public.emergency_notice_daily_receipts(announcement_id text not null,customer_id uuid not null references auth.users(id) on delete cascade,confirmed_date date not null,confirmed_at timestamptz not null default now(),primary key(announcement_id,customer_id,confirmed_date));
alter table public.emergency_notice_daily_receipts enable row level security;
revoke all on public.emergency_notice_daily_receipts from anon,authenticated;
drop function if exists public.get_today_emergency_notices();
create or replace function public.get_today_emergency_notices() returns table(announcement_id text,notice_type text,title text,content text,image_url text,link_url text,start_at timestamptz,end_at timestamptz) language sql security definer set search_path=public stable as $$ select a.id::text,a.notice_type,a.title,a.content,a.image_url,a.link_url,a.start_at,a.end_at from public.announcements a join public.customers c on c.id=auth.uid() where auth.uid() is not null and coalesce(c.is_admin,false)=false and a.popup_enabled=true and a.is_published=true and (coalesce(array_length(a.popup_target_grades,1),0)=0 or coalesce(c.customer_grade,'일반')=any(a.popup_target_grades) or (coalesce(c.customer_grade,'일반')='우수고객' and '우수'=any(a.popup_target_grades))) and coalesce(a.start_at,now())<=now() and (a.end_at is null or a.end_at>=now()) and not exists(select 1 from public.emergency_notice_daily_receipts r where r.announcement_id=a.id::text and r.customer_id=auth.uid() and r.confirmed_date=(now() at time zone 'Asia/Seoul')::date) order by case when a.notice_type='긴급공지' then 0 else 1 end,a.is_pinned desc,a.created_at desc;$$;
create or replace function public.confirm_today_emergency_notice(p_announcement_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_user uuid:=auth.uid();v_is_admin boolean;begin if v_user is null then raise exception '로그인이 필요합니다.';end if;select coalesce(is_admin,false) into v_is_admin from public.customers where id=v_user;if coalesce(v_is_admin,false) then raise exception '거래처 계정만 확인할 수 있습니다.';end if;if not exists(select 1 from public.announcements where id::text=p_announcement_id and popup_enabled=true and is_published=true) then raise exception '팝업 공지를 찾을 수 없습니다.';end if;insert into public.emergency_notice_daily_receipts(announcement_id,customer_id,confirmed_date) values(p_announcement_id,v_user,(now() at time zone 'Asia/Seoul')::date) on conflict(announcement_id,customer_id,confirmed_date) do update set confirmed_at=now();return jsonb_build_object('ok',true);end $$;
revoke all on function public.get_today_emergency_notices() from public;revoke all on function public.confirm_today_emergency_notice(text) from public;grant execute on function public.get_today_emergency_notices() to authenticated;grant execute on function public.confirm_today_emergency_notice(text) to authenticated;
commit;
